        lda #$46
        sta COLUPF          ; red: ball
        lda #$B6
        sta COLUP1          ; green: missile 1
        lda #$80
        sta GRP0            ; one pixel, leftmost bit of the player
        lda #2
        sta ENAM1
        sta ENABL

